		description: 'Commonly referred to as the "Wasp" among the crews of Argon ships, this rocket system is fitted with a target-data processor instead of the technologically advanced guidance systems found on more expensive weapons. As a non-guided weapon, it does not possess the means to compensate for changes in the target\'s trajectory. While use against agile targets is therefore not advised, when used against slower targets the Wasp allows pilots to punch significantly above their weight without having to invest in more expensive missile-based weapons.\n\nThe Breaching variant uses a ceramics-sheathed warhead with a modulated charge to achieve partial shield-piercing characteristics. The financial wisdom of using such complex and expensive materials on a budget rocket may be questionable, but its humbling impact is not.',
