		version: 0,
		name: 'S Burst Ray Mk1',
		description: 'The Burst Ray is a short-range weapon system optimised for disabling capital ship surface elements. It delivers damage through rapid, sequenced emissions that apply concentrated radiation beams to exposed subsystems, causing the target\'s surface to lose molecular cohesion. This makes it particularly effective against engines, shield generators, and turret installations.\n\nThis specialised role comes with clear limitations. The Burst Ray exhibits limited effectiveness against primary shield arrays and hull structures, and its short engagement range restricts its utility in general-purpose combat, particularly against small and medium-sized vessels. The instantaneous application of its individual beams can nevertheless offer situational effectiveness against small and evasive targets.\n\nThe weapon\'s development is attributed to initiatives within the Paranid theocracy, reportedly commissioned in response to an increasing reliance on heavy fleets and long-range armaments during internal doctrinal shifts.',
