		id: 'weapon_gen_s_cannon_01_mk1',
		version: 0,
		name: 'S Blast Mortar Mk1',
		description: 'The Blast Mortar fires a compact high-explosive charge encapsulated by superheated chondritic material. A proximity fuse triggers detonation near the target, with a wide blast radius compensating for the system\'s limited accuracy. The affected area is sufficient to neutralise multiple surface elements on capital ships with a single discharge.\n\nIt is often compared favourably to the Plasma Cannon due to its higher projectile velocity, enabling limited engagement of smaller targets when required. However, it is not a flak weapon and is most effectively employed against medium or larger vessels that cannot readily evade fire.\n\nDeveloped before the formal proclamation of the Holy Order of the Pontifex, the Blast Mortar reflects early Paranid efforts to maximise combat effectiveness under constrained industrial capacity. The result is a weapon that combines high destructive output with relative manufacturing simplicity.',
