		version: 0,
		name: 'S Shard Battery Mk1',
		description: 'The Shard Battery is a short-range kinetic weapon system characterised by the simultaneous discharge of multiple projectiles. This configuration compensates for limited accuracy and effective range by delivering high damage against both shields and hulls. Functionally, the system is derived from the Bolt Repeater, though the requirement for a wider barrel aperture and increased projectile spacing results in higher energy consumption.\n\nIn terms of raw damage output, the Shard Battery is often compared to the Plasma Cannon, though it serves a different tactical role. It performs most effectively against larger, slower targets such as M-sized vessels, which are less able to evade its projectile spread. The weapon is also well suited to engaging capital ship surface elements from inside their defensive turrets\' dead angle.',
