		version: 0,
		name: 'TEL Phoenix Main Battery',
		description: 'Early production runs of the Phoenix destroyer incorporated weapon systems derived from both Argon and Paranid designs. While expedient, this approach exposed the Teladi Company to prolonged legal disputes, resulting in reduced confidence in external licencing arrangements. The matter was ultimately settled out of court, prompting the accelerated development of a proprietary main battery derived from Muon Disintegrator technology.\n\nOfficially, this new weapon was advertised as a significant improvement over the Behemoth\'s primary armament; however, comparative assessments indicated broadly equivalent performance. Its defining characteristics are inherited from smaller Muon-based systems, delivering enhanced damage against shield systems while inhibiting shield and travel drive recharge. While these properties align with the Phoenix\'s high-mobility doctrine, they have also seen use among illegal operators.',
