		description: 'The Disruptor missile might be one of the most insidious missile systems currently available. It is likely that the weapon was reverse engineered from the Hamstring EMP-system. While the Hamstring is a non-harmful weapon that causes no lasting damage to the target and leaves the crews unharmed, the Disruptor missile has no such limitations. Using a modified copy of the Hamstring\'s Peregrine engine, it accelerates to a brisk pace in pursuit of its target. When the missile gets close enough to its target, it brutally attacks, not just with an electromagnetic pulse discharge, but also by allowing its reactor to go critical and subsequently detonate. The electromagnetic pulse is blasted into the target vessel moments before a violent explosion wreaks havoc on its control and guidance systems. This level of interference is enough to trick a target vessel\'s security protocols into triggering emergency shutdowns of their own propulsion systems, leaving them effectively immobilised for roughly the duration of a short system scan and reboot. Like the Hamstring, the extreme speeds provided by the Peregrine engine system mean that the Disruptor missile can be a difficult to control.',
		type: EquipmentType.missiles,
		equipmentClass: EquipmentClass.missile,
		explosionDamage: 900,
		hull: 1,
		price: { min: 866, max: 1171, avg: 1018 },
