		name: 'SPL M Tau Accelerator Turret Mk1',
		description: 'The Tau Accelerator is a short-range kinetic weapon optimised for high-impact engagements. Owing to its Split design, the Tau Accelerator delivers destructive force similar to the Shard Battery while its rapid rate of fire produces a demoralising effect on enemy combatants.\n\nCompared to the Shard Battery, the Tau Accelerator delivers higher per-shot energy output and a tighter projectile spread. These gains are offset by reduced heat dissipation efficiency, shorter effective range, and a lower projectile count with diminished velocity. As a result, the weapon is most effective at close proximity, where its high rate of fire can rapidly overwhelm exposed targets before thermal limits are reached.\n\nThe Tau Accelerator remains in common use among Split bounty hunters, for whom close-range engagement is standard practice. In this operational context, its thermal constraints and limited reach are considered acceptable trade-offs for concentrated firepower and rapid target neutralisation.',
