		version: 2,
		name: 'TER L Meson Stream Turret Mk1',
		description: 'The Meson Stream is a high-output beam weapon designed for extreme-range engagements. It emits a single transient beam that reaches the target at relativistic velocities. As is the case with other high-precision systems, its limited gimbal envelope restricts its effectiveness against nearby or fast-moving targets. This limitation is largely mitigated by the weapon\'s optical configuration, which is optimised for long-range focus. At distances below its effective range, beam coherence degrades rapidly, resulting in a steep reduction in destructive output.\n\nDue to its exceptionally high energy demand and thermal load, the Meson Stream can only be installed on high-energy weapon mounts.\n\nThe system borrows its concept from large-scale directed-energy weapons first explored by the now defunct Terran AGI Task Force. Although it required the development of an entirely novel platform and operates with a notably inefficient energy profile, its value as a long-range deterrent was considered sufficient to justify these constraints. The Meson Stream represents the first operational result of this programme, marking an initial but deliberate step by the Terran Protectorate toward fielding super-heavy directed-energy armaments.',
