		description: 'The Terran Proton Barrage is a short-range weapon system compatible exclusively with high-energy weapon mounts. It represents the Terran high-energy counterpart to the Commonwealth Bolt Repeater. Compared to its Commonwealth equivalent, the Proton Barrage offers increased damage output and projectile velocity at the expense of effective range. While delivering greater overall damage, it operates at a lower rate of fire, favouring more powerful individual projectiles during extended bursts.\n\nThe system is restricted to Terran ship designs due to its mount requirements and it carries a significantly higher acquisition cost than the standard Bolt Repeater. Despite these limitations, the Proton Barrage fulfils a general-purpose role and performs effectively across a broad range of target profiles.\n\nThe origins of the Terran Proton Barrage began after the reconnection with the Commonwealth, when the Terran Secret Service obtained Bolt Repeater design blueprints, enabling Terran engineers to refine its design and develop adjustments for high-energy mount capability. These modifications resulted in increased power output while producing a weapon system distinct from its Commonwealth predecessor.',
