		version: 2,
		name: 'TER M Pulse Laser Mk1',
		description: 'The Terran Pulse Laser is a variant of the standard pulse-based weapon widely deployed throughout the Jump Gate network, and incorporates superior Terran optics. While its effective range is shorter than most Commonwealth implementations, higher projectile velocity, and the resulting reduction of in-flight time, improve overall hit consistency. As with comparable pulse weapons, it favours sustained fire and continuous target tracking over short, high-damage engagements.\n\nFollowing the Gate Realignment, the Terran Protectorate evaluated contemporary armaments and adapted the existing Pulse Laser design to Terran manufacturing standards. The resulting system preserves the weapon\'s core operating principles while incorporating structural and optical changes intended to restrict unauthorised replication. Although initially considered unsuitable for use by foreign arms providers, the design has since been integrated into a diverse range of vessels with only minor compromises.',
