		version: 3,
		name: 'Erlking M Turret',
		description: 'The Erlking M Turret fires bursts of high speed projectiles, reminiscent of Bolt Repeater burst fire. While fixed weapons usually outperform their turret counterparts of the same size, the Erlking\'s turrets are an unusual exception; the damage from this turret is comparable to, and might even exceed, that of M Bolt Repeater weapons at close range. Over distance, however, the damage output falls off steeply, and at maximum range barely matches that of a standard M Bolt Repeater turret. Although the Erlking is perfectly capable of defending itself at a distance, the high damage output of its turrets at short range makes it much more dangerous at close proximity, meaning that aggressive manoeuvres by the Erlking\'s pilot are rewarded. This exceptional performance is attributed to the Erlking\'s power core, from which the turrets draw energy.\n\nBoso Ta was particularly keen to go into detail about how this turret manages to rapidly access the power core, for only the blink of an eye at a time, before just as rapidly cutting the connection, thereby preventing an energy draining feedback loop capable of destroying the ship. Boso Ta also said not to worry, as the safety mechanisms will prevent this from happening most of the time.',
